    p_voice = sub.add_parser("voice", help="enter the existing OMEGA Realtime voice organ")
    p_voice.add_argument("args", nargs=argparse.REMAINDER)
    p_grf = sub.add_parser("grf", help="compile/project GRF state for the canonical GRID10 J-Space")
    p_grf.add_argument("args", nargs=argparse.REMAINDER)
    ns = ap.parse_args(argv)

    if ns.command in (None, "status"):
        print(json.dumps(manifest(), ensure_ascii=False, indent=2))
        return 0
    if ns.command == "selftest":
        result = selftest()
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return 0 if result["ok"] else 1
    if ns.command == "fred-selftest":
        args = ["--owner", ns.owner, "--machine-id", ns.machine_id]
        if ns.host:
            args.append("--host")
        return subprocess.call([sys.executable, str(HERE / "omega_fred_selftest.py"), *args])
    if ns.command == "organ-status":
        return _organ_status()
    if ns.command == "terminal":
