    if ns.command == "voice":
        return _exec_script(HERE / "voice_777_runtime.py", list(ns.args))
    if ns.command == "grf":
        return _exec_script(HERE / "omega_grf_brain.py", list(ns.args))
    return 2


if __name__ == "__main__":
